var documents_component_default2 = `/* src/app/documents/documents.component.css */
.documents-container {
  min-height: 100vh;
  color: #333333;
}
.hero-section {
  background:
    linear-gradient(
      135deg,
      rgba(0, 0, 0, 0.6) 0%,
      rgba(0, 0, 0, 0.3) 100%);
  padding: 6rem 2rem 3rem;
  text-align: center;
  position: relative;
}
.hero-section::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="rgba(255,255,255,0.1)" stroke-width="0.5"/></pattern></defs><rect width="100" height="100" fill="url(%23grid)"/></svg>');
  z-index: -1;
}
.hero-content {
  max-width: 800px;
  margin: 0 auto;
}
.hero-title {
  font-size: 3rem;
  font-weight: 700;
  margin: 0 0 1rem 0;
  color: #ffffff;
  animation: fadeInUp 0.8s ease-out forwards;
  opacity: 0;
  transform: translateY(20px);
}
.hero-subtitle {
  font-size: 1.2rem;
  color: #e0e0e0;
  margin: 0;
  font-weight: 400;
  animation: fadeInUp 0.8s ease-out 0.2s forwards;
  opacity: 0;
  transform: translateY(20px);
}
.content-section {
  padding: 3rem 2rem;
}
.container {
  max-width: 1200px;
  margin: 0 auto;
}
.upload-section {
  margin-bottom: 3rem;
}
.upload-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(0, 0, 0, 0.05);
}
.section-title {
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0 0 1.5rem 0;
  color: #333333;
}
.file-upload {
  position: relative;
}
.file-input {
  position: absolute;
  opacity: 0;
  width: 100%;
  height: 100%;
  cursor: pointer;
}
.file-label {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 2rem;
  border: 2px dashed #dee2e6;
  border-radius: 12px;
  background: #f8f9fa;
  transition: all 0.3s ease;
  cursor: pointer;
}
.file-label:hover {
  border-color: #007bff;
  background: #f0f8ff;
}
.upload-icon {
  font-size: 3rem;
  margin-bottom: 1rem;
}
.upload-text {
  font-size: 1.1rem;
  color: #6c757d;
  font-weight: 500;
}
.documents-section {
  margin-bottom: 2rem;
}
.documents-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 2rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(0, 0, 0, 0.05);
}
.documents-grid {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.document-item {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.5rem;
  background: #f8f9fa;
  border-radius: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  border: 1px solid transparent;
}
.document-item:hover {
  background: #e9ecef;
  border-color: #dee2e6;
  transform: translateX(5px);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1);
}
.document-icon {
  font-size: 2rem;
  flex-shrink: 0;
}
.document-content {
  flex: 1;
}
.document-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin: 0 0 0.5rem 0;
  color: #333333;
}
.document-description {
  font-size: 0.9rem;
  color: #6c757d;
  margin: 0;
  line-height: 1.4;
}
.document-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}
.delete-btn {
  background: none;
  border: none;
  font-size: 1.2rem;
  cursor: pointer;
  padding: 0.5rem;
  border-radius: 6px;
  transition: all 0.2s ease;
}
.delete-btn:hover {
  background: #f8d7da;
  color: #721c24;
}
.document-arrow {
  font-size: 1.2rem;
  color: #007bff;
  transition: transform 0.2s ease;
}
.document-item:hover .document-arrow {
  transform: translateX(5px);
}
.no-documents {
  text-align: center;
  padding: 3rem 0;
}
.no-documents-card {
  background: #ffffff;
  border-radius: 16px;
  padding: 3rem 2rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
  border: 1px solid rgba(0, 0, 0, 0.05);
  max-width: 500px;
  margin: 0 auto;
}
.no-documents-icon {
  font-size: 4rem;
  margin-bottom: 1.5rem;
}
.no-documents-card h3 {
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0 0 1rem 0;
  color: #333333;
}
.no-documents-card p {
  font-size: 1rem;
  color: #6c757d;
  margin: 0;
}
.modern-accordion ::ng-deep .p-accordion .p-accordion-header .p-accordion-header-link {
  background: #f8f9fa;
  border: 1px solid #dee2e6;
  border-radius: 8px;
  padding: 1rem 1.5rem;
  font-weight: 600;
  color: #333333;
}
.modern-accordion ::ng-deep .p-accordion .p-accordion-header:not(.p-disabled).p-highlight .p-accordion-header-link {
  background: #007bff;
  border-color: #007bff;
  color: #ffffff;
}
.modern-accordion ::ng-deep .p-accordion .p-accordion-content {
  border: none;
  padding: 1rem 0;
}
.modal-backdrop {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.8);
  z-index: 1000;
  backdrop-filter: blur(15px);
  display: none;
}
.modal-backdrop.active {
  display: block;
}
app-viewer {
  position: fixed;
  z-index: 1001;
  background: rgba(0, 0, 0, 0.95);
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 20px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.7);
  padding: 3rem;
  max-width: 80%;
  max-height: 80%;
  overflow: auto;
  display: none;
  animation: fadeIn 0.3s ease-out;
}
app-viewer.active {
  display: block;
}
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes fadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (max-width: 768px) {
  .hero-section {
    padding: 5rem 1rem 2rem;
  }
  .hero-title {
    font-size: 2.5rem;
  }
  .hero-subtitle {
    font-size: 1.1rem;
  }
  .content-section {
    padding: 2rem 1rem;
  }
  .section-title {
    font-size: 1.3rem;
  }
  .upload-card,
  .documents-card {
    padding: 1.5rem;
  }
  .document-item {
    padding: 1.25rem;
  }
}
@media (max-width: 480px) {
  .hero-title {
    font-size: 2rem;
  }
  .hero-subtitle {
    font-size: 1rem;
  }
  .upload-card,
  .documents-card {
    padding: 1.25rem;
  }
  .document-item {
    flex-direction: column;
    text-align: center;
    gap: 1rem;
  }
  .document-actions {
    justify-content: center;
  }
  .no-documents-card {
    padding: 2rem 1.5rem;
  }
}
`;

