var contact_component_default = `<div class="contact-container">
  <!-- Hero Section -->
  <div class="hero-section">
    <div class="hero-content">
      <h1 class="hero-title">Contact Us</h1>
      <p class="hero-subtitle">Get in touch with our community leaders</p>
    </div>
  </div>

  <!-- Contact Information -->
  <div class="content-section">
    <div class="container">
      <!-- Board Members -->
      <div class="contact-section">
        <h2 class="section-title">Board Members</h2>
        <div class="contacts-grid">
          <div 
            *ngFor="let contact of contacts; let i = index"
            class="contact-card"
            [style.animation-delay]="(0.2 * i) + 's'"
          >
            <div class="contact-icon">
              <span class="icon">{{ getIcon(contact.icon) }}</span>
            </div>
            <div class="contact-info">
              <h3 class="contact-name">{{ contact.name }}</h3>
              <p class="contact-title">{{ contact.title }}</p>
              <a 
                href="mailto:{{ contact.email }}" 
                class="contact-email"
                [title]="contact.email"
              >
                {{ contact.email }}
              </a>
            </div>
          </div>
        </div>
      </div>

      <!-- Quick Links -->
      <div class="contact-section">
        <h2 class="section-title">Quick Links</h2>
        <div class="links-grid">
          <a 
            *ngFor="let staticPage of staticPages; let i = index"
            href="{{ staticPage.href }}"
            target="_blank"
            class="link-card"
            [style.animation-delay]="(0.2 * i) + 's'"
          >
            <div class="link-icon">
              <span class="icon">{{ getIcon(staticPage.icon) }}</span>
            </div>
            <div class="link-content">
              <h3 class="link-name">{{ staticPage.name }}</h3>
              <p class="link-description">{{ staticPage.title }}</p>
            </div>
            <div class="link-arrow">\u2192</div>
          </a>
        </div>
      </div>
    </div>
  </div>
</div>
`;

